      { q: 'सर्वप्रथम किस वैज्ञानिक ने खोजा कि विद्युत धारा के प्रवाह से चुंबकीय क्षेत्र उत्पन्न होता है?', a: 'हंस क्रिश्चियन ओर्स्टेड (1820)', opts: ['माइकल फैराडे', 'हंस क्रिश्चियन ओर्स्टेड (1820)', 'आइजैक न्यूटन', 'आंद्रे मैरी एम्पीयर'], correct: 'B', sol: 'ओर्स्टेड ने तार के पास रखी कंपास सुई का विक्षेप देखकर यह खोज की।' },
      { q: 'चुंबक के बाहर चुंबकीय क्षेत्र रेखाओं की दिशा किस ध्रुव से किस ध्रुव की ओर होती है?', a: 'उत्तरी ध्रुव (N) से दक्षिणी ध्रुव (S) की ओर', opts: ['दक्षिणी से उत्तरी', 'उत्तरी ध्रुव (N) से दक्षिणी ध्रुव (S) की ओर', 'पूर्व से पश्चिम', 'केंद्र से बाहर'], correct: 'B', sol: 'बाहर N से S तथा चुंबक के अंदर S से N की ओर बंद वक्र बनाती हैं।' },
      { q: 'दो चुंबकीय क्षेत्र रेखाएं कभी एक-दूसरे को प्रतिच्छेद क्यों नहीं करतीं?', a: 'प्रतिच्छेद बिंदु पर कंपास सुई दो दिशाएं दर्शाएगी जो असंभव है', opts: ['ये समानांतर होती हैं', 'प्रतिच्छेद बिंदु पर कंपास सुई दो दिशाएं दर्शाएगी जो असंभव है', 'ये सीधी रेखाएं हैं', 'ये काल्पनिक हैं'], correct: 'B', sol: 'एक ही बिंदु पर चुंबकीय क्षेत्र की दो दिशाएं संभव नहीं हैं।' },
      { q: 'सीधे धारावाही चालक तार के चारों ओर चुंबकीय क्षेत्र की दिशा ज्ञात करने का नियम है:', a: 'दक्षिण हस्त अंगुष्ठ नियम (Right-Hand Thumb Rule)', opts: ['फ्लेमिंग का वाम हस्त नियम', 'दक्षिण हस्त अंगुष्ठ नियम (Right-Hand Thumb Rule)', 'स्नेल का नियम', 'ओम का नियम'], correct: 'B', sol: 'अंगूठा धारा की दिशा में हो तो मुड़ी हुई अंगुलियां चुंबकीय क्षेत्र रेखाएं दर्शाती हैं।' },
      { q: 'परिनालिका (Solenoid) के भीतर चुंबकीय क्षेत्र कैसा होता है?', a: 'सभी बिंदुओं पर एकसमान तथा समानांतर', opts: ['शून्य', 'सभी बिंदुओं पर एकसमान तथा समानांतर', 'सिरों पर शून्य', 'परिवर्तनशील'], correct: 'B', sol: 'परिनालिका के अंदर क्षेत्र रेखाएं समानांतर होती हैं जो एकसमान क्षेत्र दर्शाती हैं।' },
      { q: 'विद्युत चुंबक (Electromagnet) बनाने के लिए किस प्रकार के लोहे की क्रोड का उपयोग किया जाता है?', a: 'नरम लोहे (Soft Iron) की छड़', opts: ['इस्पात (Steel)', 'नरम लोहे (Soft Iron) की छड़', 'तांबा', 'एल्युमिनियम'], correct: 'B', sol: 'नरम लोहा धारा बंद होते ही अपना चुंबकत्व तुरंत खो देता है।' },
      { q: 'चुंबकीय क्षेत्र में रखे धारावाही चालक पर आरोपित बल किस नियम द्वारा ज्ञात किया जाता है?', a: 'फ्लेमिंग का वामहस्त नियम (Left-Hand Rule)', opts: ['फ्लेमिंग का दक्षिण हस्त नियम', 'फ्लेमिंग का वामहस्त नियम (Left-Hand Rule)', 'मैक्सवेल का कॉर्क स्क्रू नियम', 'फैराडे का नियम'], correct: 'B', sol: 'तर्जनी = क्षेत्र, मध्यमा = धारा, अँगूठा = बल की दिशा।' },
      { q: 'फ्लेमिंग के वामहस्त नियम में अँगूठा किसकी दिशा प्रदर्शित करता है?', a: 'चालक पर आरोपित बल या गति की दिशा', opts: ['चुंबकीय क्षेत्र की', 'विद्युत धारा की', 'चालक पर आरोपित बल या गति की दिशा', 'प्रेरित धारा की'], correct: 'C', sol: 'अँगूठा बल/गति (F), तर्जनी चुंबकीय क्षेत्र (B), मध्यमा धारा (I) दर्शाती है।' },
      { q: 'भारत में घरों में प्रयुक्त प्रत्यावर्ती धारा (AC) की आवृत्ति कितनी होती है?', a: '50 हर्ट्ज (Hz)', opts: ['60 Hz', '50 हर्ट्ज (Hz)', '100 Hz', '220 Hz'], correct: 'B', sol: 'भारतीय घरेलू आपूर्ति 220 V पर 50 Hz आवृत्ति की होती है।' },
      { q: 'घरेलू वायरिंग में विद्युन्मय तार (Live Wire) पर सामान्यतः किस रंग का आवरण होता है?', a: 'लाल रंग (Red)', opts: ['काला रंग', 'लाल रंग (Red)', 'हरा रंग', 'नीला रंग'], correct: 'B', sol: 'विद्युन्मय तार लाल, उदासीन तार काला, तथा भू-संपर्क तार हरा होता है।' },
      { q: 'घरेलू वायरिंग में भू-सम्पर्क तार (Earth Wire) का मुख्य सुरक्षा कार्य क्या है?', a: 'उपकरण के धात्विक आवरण से रिसाव धारा को भूमि में भेजकर बिजली के झटके से बचाना', opts: ['विद्युत बिल कम करना', 'उपकरण के धात्विक आवरण से रिसाव धारा को भूमि में भेजकर बिजली के झटके से बचाना', 'धारा बढ़ाना', 'वोल्टेज स्थिर रखना'], correct: 'B', sol: 'यह नगण्य प्रतिरोध का मार्ग देकर उपभोक्ता को घातक झटके से बचाता है।' },
      { q: 'लघुपथन (Short Circuit) के समय परिपथ में विद्युत धारा का मान:', a: 'अत्यधिक बढ़ जाता है', opts: ['शून्य हो जाता है', 'अत्यधिक बढ़ जाता है', 'अपरिवर्तित रहता है', 'कम हो जाता है'], correct: 'B', sol: 'लाइव और न्यूट्रल तार सीधे संपर्क में आने से प्रतिरोध शून्य हो जाता है और धारा तीव्र गति से बढ़ती है।' },
      { q: 'अतिभारण (Overloading) का मुख्य कारण क्या है?', a: 'एक ही सॉकेट से अत्यधिक उच्च शक्ति वाले उपकरणों का एक साथ चलाना', opts: ['वोल्टेज बढ़ना', 'एक ही सॉकेट से अत्यधिक उच्च शक्ति वाले उपकरणों का एक साथ चलाना', 'तार का टूटना', 'स्विच खराब होना'], correct: 'B', sol: 'अधिक उपकरण जोड़ने पर कुल धारा स्वीकृत सीमा से बढ़ जाती है।' },
      { q: 'चुंबकीय क्षेत्र की तीव्रता का SI मात्रक क्या है?', a: 'टेस्ला (Tesla - T)', opts: ['वेबर', 'टेस्ला (Tesla - T)', 'गॉस', 'न्यूटन'], correct: 'B', sol: 'चुंबकीय क्षेत्र का मात्रक टेस्ला (T) होता है।' },
      { q: 'किसी चुंबकीय क्षेत्र के लंबवत गतिमान इलेक्ट्रॉन पर आरोपित बल की दिशा होगी:', a: 'इलेक्ट्रॉन की गति के विपरीत दिशा में प्रवाहित धारा मानकर फ्लेमिंग के नियम अनुसार', opts: ['इलेक्ट्रॉन की गति की दिशा में', 'इलेक्ट्रॉन की गति के विपरीत दिशा में प्रवाहित धारा मानकर फ्लेमिंग के नियम अनुसार', 'क्षेत्र की दिशा में', 'शून्य'], correct: 'B', sol: 'ऋणावेशित इलेक्ट्रॉन की गति के विपरीत पारंपरिक धारा मानी जाती है।' }
